    Point leftmost = *minmax.first;
    Point rightmost = *minmax.second;

    // Partition into upper and lower sets
    std::vector<Point> upper, lower;
    for (const auto& p : points) {
        double cp = cross(leftmost, rightmost, p);
        if (cp > 0) upper.push_back(p);
        else if (cp < 0) lower.push_back(p);
    }

    // Compute hulls in parallel
    auto f_upper = hpx::async([&]{ 
        std::vector<Point> h;
        quickHull(upper, leftmost, rightmost, h);
        return h;
    });
    auto f_lower = hpx::async([&]{ 
        std::vector<Point> h;
        quickHull(lower, rightmost, leftmost, h);
        return h;
    });

    hull.push_back(leftmost);
    auto h_upper = f_upper.get();
    hull.insert(hull.end(), h_upper.begin(), h_upper.end());
    hull.push_back(rightmost);
    auto h_lower = f_lower.get();
    hull.insert(hull.end(), h_lower.begin(), h_lower.end());
