void convexHull(std::vector<Point> const& points, std::vector<Point>& hull) {
    hull.clear();

    int n = points.size();
    if (n < 3) {
        hull = points;
        return;
    }

    // Sort points lexicographically using HPX parallel sort
    std::vector<Point> sorted = points;
    hpx::sort(hpx::execution::par, sorted.begin(), sorted.end(),
        [](const Point& a, const Point& b) {
            return a.x < b.x || (a.x == b.x && a.y < b.y);
        });

    // Build lower hull
    std::vector<Point> lower;
    for (int i = 0; i < n; i++) {
        while (lower.size() >= 2 && 
               cross(lower[lower.size()-2], lower[lower.size()-1], sorted[i]) <= 0) {
            lower.pop_back();
        }
        lower.push_back(sorted[i]);
    }

    // Build upper hull
    std::vector<Point> upper;
    for (int i = n - 1; i >= 0; i--) {
        while (upper.size() >= 2 && 
               cross(upper[upper.size()-2], upper[upper.size()-1], sorted[i]) <= 0) {
            upper.pop_back();
        }
        upper.push_back(sorted[i]);
    }

    // Remove last point of each half because they are repeated
    lower.pop_back();
    upper.pop_back();

    // Concatenate lower and upper hull
    hull = std::move(lower);
    hull.insert(hull.end(), upper.begin(), upper.end());
}

void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    hull.clear();
    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Find the bottom-most point (leftmost if tie) - guaranteed on hull
    Point pivot = *hpx::min_element(hpx::execution::par, 
        points.begin(), points.end(),
        [](const Point& a, const Point& b) {
            return a.y < b.y || (a.y == b.y && a.x < b.x);
        });

    // Sort points by polar angle with respect to pivot (parallel sort)
    std::vector<Point> sorted_points = points;
    hpx::sort(hpx::execution::par, sorted_points.begin(), sorted_points.end(),
        [&pivot](const Point& a, const Point& b) {
            if (a.x == pivot.x && a.y == pivot.y) return true;
            if (b.x == pivot.x && b.y == pivot.y) return false;

            // Cross product to determine orientation
            double cross = (a.x - pivot.x) * (b.y - pivot.y) - 
                          (a.y - pivot.y) * (b.x - pivot.x);

            if (std::abs(cross) < 1e-9) {
                // Collinear - closer point first
                double dist_a = (a.x - pivot.x) * (a.x - pivot.x) + 
                               (a.y - pivot.y) * (a.y - pivot.y);
                double dist_b = (b.x - pivot.x) * (b.x - pivot.x) + 
                               (b.y - pivot.y) * (b.y - pivot.y);
                return dist_a < dist_b;
            }
            return cross > 0; // Counter-clockwise
        });

    // Graham scan to build hull
    auto ccw = [](const Point& a, const Point& b, const Point& c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    };

    hull.push_back(sorted_points[0]);
    hull.push_back(sorted_points[1]);

    for (size_t i = 2; i < sorted_points.size(); i++) {
        while (hull.size() > 1 && 
               ccw(hull[hull.size()-2], hull[hull.size()-1], sorted_points[i]) <= 0) {
            hull.pop_back();
        }
        hull.push_back(sorted_points[i]);
    }
}

void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    hull.clear();
    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Sort points by x-coordinate (parallel sort with HPX)
    std::vector<Point> sorted_points = points;
    hpx::sort(hpx::execution::par, sorted_points.begin(), sorted_points.end(),
              [](const Point& a, const Point& b) {
                  return a.x < b.x || (a.x == b.x && a.y < b.y);
              });

    // Cross product to determine turn direction (counter-clockwise > 0)
    auto cross = [](const Point& O, const Point& A, const Point& B) {
        return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
    };

    // Build lower hull (Andrew's monotone chain algorithm)
    std::vector<Point> lower;
    for (const auto& p : sorted_points) {
        while (lower.size() >= 2 && 
               cross(lower[lower.size()-2], lower[lower.size()-1], p) <= 0) {
            lower.pop_back();
        }
        lower.push_back(p);
    }

    // Build upper hull
    std::vector<Point> upper;
    for (int i = sorted_points.size() - 1; i >= 0; i--) {
        const auto& p = sorted_points[i];
        while (upper.size() >= 2 && 
               cross(upper[upper.size()-2], upper[upper.size()-1], p) <= 0) {
            upper.pop_back();
        }
        upper.push_back(p);
    }

    // Remove duplicate endpoints
    lower.pop_back();
    upper.pop_back();

    // Combine lower and upper hulls
    hull = std::move(lower);
    hull.insert(hull.end(), upper.begin(), upper.end());
}

