    hpx::sort(hpx::execution::par, sorted_points.begin(), sorted_points.end(),
              [](const Point& a, const Point& b) {
                  return a.x < b.x || (a.x == b.x && a.y < b.y);
              });

    // Build lower hull
    std::vector<Point> lower;
    for (const auto& p : sorted_points) {
        while (lower.size() >= 2 && 
               cross(lower[lower.size()-2], lower[lower.size()-1], p) <= 0) {
            lower.pop_back();
        }
        lower.push_back(p);
    }

    // Build upper hull
    std::vector<Point> upper;
    for (auto it = sorted_points.rbegin(); it != sorted_points.rend(); ++it) {
        while (upper.size() >= 2 && 
               cross(upper[upper.size()-2], upper[upper.size()-1], *it) <= 0) {
            upper.pop_back();
        }
        upper.push_back(*it);
    }

    // Remove last point of each half because it's repeated
    lower.pop_back();
    upper.pop_back();

    // Concatenate lower and upper hull
    hull.reserve(lower.size() + upper.size());
    hull.insert(hull.end(), lower.begin(), lower.end());
    hull.insert(hull.end(), upper.begin(), upper.end());
