void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    hull.clear();
    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Find the point with lowest y-coordinate (leftmost if tie)
    auto start_it = hpx::min_element(hpx::execution::par,
        points.begin(), points.end(),
        [](const Point& a, const Point& b) {
            return a.y < b.y || (a.y == b.y && a.x < b.x);
        });
    Point start = *start_it;

    // Sort points by polar angle with respect to start point
    std::vector<Point> sorted_points = points;
    hpx::sort(hpx::execution::par, sorted_points.begin(), sorted_points.end(),
        [&start](const Point& a, const Point& b) {
            if (a.x == start.x && a.y == start.y) return true;
            if (b.x == start.x && b.y == start.y) return false;

            double dx1 = a.x - start.x, dy1 = a.y - start.y;
            double dx2 = b.x - start.x, dy2 = b.y - start.y;
            double cross = dx1 * dy2 - dy1 * dx2;

            if (cross != 0) return cross > 0;
            // Collinear: closer point first
            return dx1 * dx1 + dy1 * dy1 < dx2 * dx2 + dy2 * dy2;
        });

    // Graham scan
    auto ccw = [](const Point& a, const Point& b, const Point& c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    };

    hull.push_back(sorted_points[0]);
    for (size_t i = 1; i < sorted_points.size(); i++) {
        while (hull.size() > 1 && 
               ccw(hull[hull.size()-2], hull[hull.size()-1], sorted_points[i]) <= 0) {
            hull.pop_back();
        }
        hull.push_back(sorted_points[i]);
    }
}

void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
