        hull = points;
        return;
    }

    // Find the bottom-most point (left-most if tied) using parallel min_element
    auto start_it = hpx::min_element(hpx::execution::par, 
        points.begin(), points.end(),
        [](const Point& a, const Point& b) {
            return a.y < b.y || (a.y == b.y && a.x < b.x);
        });
    Point start = *start_it;

    // Cross product to determine turn direction
    auto cross = [](const Point& O, const Point& A, const Point& B) {
        return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
    };

    // Sort points by polar angle with respect to start point using parallel sort
    std::vector<Point> sorted_points = points;
    hpx::sort(hpx::execution::par, sorted_points.begin(), sorted_points.end(),
        [&start, &cross](const Point& a, const Point& b) {
            if (a.x == start.x && a.y == start.y) return true;
            if (b.x == start.x && b.y == start.y) return false;

            double c = cross(start, a, b);
            if (c == 0) {
                // Collinear - sort by distance
                double dist_a = (a.x - start.x) * (a.x - start.x) + (a.y - start.y) * (a.y - start.y);
                double dist_b = (b.x - start.x) * (b.x - start.x) + (b.y - start.y) * (b.y - start.y);
                return dist_a < dist_b;
            }
            return c > 0;
        });

    // Build hull using Graham scan (sequential part)
    hull.push_back(sorted_points[0]);
    hull.push_back(sorted_points[1]);

    for (size_t i = 2; i < sorted_points.size(); i++) {
        while (hull.size() > 1 && cross(hull[hull.size()-2], hull[hull.size()-1], sorted_points[i]) <= 0) {
            hull.pop_back();
        }
        hull.push_back(sorted_points[i]);
    }
}

