void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    hull.clear();
    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Find the bottom-most point (or left most in case of tie) using HPX parallel algorithm
    auto bottom = hpx::min_element(
        hpx::execution::par,
        points.begin(), points.end(),
        [](const Point& a, const Point& b) {
            return a.y < b.y || (a.y == b.y && a.x < b.x);
        }
    );

    Point pivot = *bottom;

    // Copy and sort points by polar angle with respect to pivot using HPX parallel sort
    std::vector<Point> sorted_points = points;

    hpx::sort(
        hpx::execution::par,
        sorted_points.begin(), sorted_points.end(),
        [&pivot](const Point& a, const Point& b) {
            if (a.x == pivot.x && a.y == pivot.y) return true;
            if (b.x == pivot.x && b.y == pivot.y) return false;

            double angle_a = std::atan2(a.y - pivot.y, a.x - pivot.x);
            double angle_b = std::atan2(b.y - pivot.y, b.x - pivot.x);

            if (std::abs(angle_a - angle_b) < 1e-9) {
                double dist_a = (a.x - pivot.x) * (a.x - pivot.x) + (a.y - pivot.y) * (a.y - pivot.y);
                double dist_b = (b.x - pivot.x) * (b.x - pivot.x) + (b.y - pivot.y) * (b.y - pivot.y);
                return dist_a < dist_b;
            }
            return angle_a < angle_b;
        }
    );

    // Graham scan to build the convex hull
    auto cross = [](const Point& O, const Point& A, const Point& B) {
        return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
    };

    for (const auto& p : sorted_points) {
        while (hull.size() >= 2 && cross(hull[hull.size()-2], hull[hull.size()-1], p) <= 0) {
            hull.pop_back();
        }
        hull.push_back(p);
    }
}

void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
