void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    hull.clear();
    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Find the bottom-most point (or left most in case of tie) using HPX parallel algorithm
    auto start_it = hpx::min_element(hpx::execution::par, 
        points.begin(), points.end(),
        [](const Point& a, const Point& b) {
            return a.y < b.y || (a.y == b.y && a.x < b.x);
        });

    Point start = *start_it;

    // Sort points by polar angle with respect to start point using HPX parallel sort
    std::vector<Point> sorted_points = points;
    hpx::sort(hpx::execution::par, sorted_points.begin(), sorted_points.end(),
        [&start](const Point& a, const Point& b) {
            if (a.x == start.x && a.y == start.y) return true;
            if (b.x == start.x && b.y == start.y) return false;

            double angle_a = std::atan2(a.y - start.y, a.x - start.x);
            double angle_b = std::atan2(b.y - start.y, b.x - start.x);

            if (std::abs(angle_a - angle_b) < 1e-9) {
                double dist_a = (a.x - start.x) * (a.x - start.x) + (a.y - start.y) * (a.y - start.y);
                double dist_b = (b.x - start.x) * (b.x - start.x) + (b.y - start.y) * (b.y - start.y);
                return dist_a < dist_b;
            }
            return angle_a < angle_b;
        });

    // Graham scan to build convex hull
    auto cross = [](const Point& O, const Point& A, const Point& B) {
        return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
    };

    for (const auto& point : sorted_points) {
        while (hull.size() >= 2 && cross(hull[hull.size()-2], hull[hull.size()-1], point) <= 0) {
            hull.pop_back();
        }
        hull.push_back(point);
    }
}

