    Point start = findStart(points);

    Point current = start;

    do {
        hull.push_back(current);

        // Find the most counterclockwise point from current
        auto next = hpx::reduce(
            hpx::execution::par,
            points.begin(), points.end(),
            points[0],
            [&current](const Point& a, const Point& b) {
                if (a.x == current.x && a.y == current.y) return b;
                if (b.x == current.x && b.y == current.y) return a;

                double cp = cross(current, a, b);
                if (cp > 0) return a;  // a is more counterclockwise
                if (cp < 0) return b;  // b is more counterclockwise

                // Collinear - choose farther point
                double dist_a = (a.x - current.x) * (a.x - current.x) + 
                               (a.y - current.y) * (a.y - current.y);
                double dist_b = (b.x - current.x) * (b.x - current.x) + 
                               (b.y - current.y) * (b.y - current.y);
                return dist_a > dist_b ? a : b;
            }
        );

        current = next;

    } while (!(current.x == start.x && current.y == start.y));
}

