    std::vector<Point> pts = points;

    // Find bottom-most point (or left-most if tied)
    size_t minIdx = 0;
    for (size_t i = 1; i < pts.size(); ++i) {
        if (pts[i].y < pts[minIdx].y || 
           (pts[i].y == pts[minIdx].y && pts[i].x < pts[minIdx].x)) {
            minIdx = i;
        }
    }
    std::swap(pts[0], pts[minIdx]);
    Point pivot = pts[0];

    // Sort by polar angle using HPX parallel sort
    auto polarAngleSort = [&pivot](Point const& a, Point const& b) {
        double cross = (a.x - pivot.x) * (b.y - pivot.y) - (a.y - pivot.y) * (b.x - pivot.x);
        if (std::abs(cross) < 1e-9) {
            return distance(pivot, a) < distance(pivot, b);
        }
        return cross > 0;
    };

    hpx::sort(hpx::execution::par, pts.begin() + 1, pts.end(), polarAngleSort);

    // Graham scan
    std::vector<Point> hull;
    hull.reserve(pts.size());

    auto ccw = [](Point const& a, Point const& b, Point const& c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    };

    for (auto const& pt : pts) {
        while (hull.size() > 1 && ccw(hull[hull.size()-2], hull[hull.size()-1], pt) <= 0) {
            hull.pop_back();
        }
        hull.push_back(pt);
    }

    // Calculate perimeter in parallel using HPX
    if (hull.size() < 2) return 0.0;

    std::vector<size_t> indices(hull.size());
    std::iota(indices.begin(), indices.end(), 0);

    double perimeter = hpx::transform_reduce(
        hpx::execution::par,
        indices.begin(), indices.end(),
        0.0,
        std::plus<>(),
        [&hull](size_t i) {
            return distance(hull[i], hull[(i + 1) % hull.size()]);
        }
    );

    return perimeter;
}

