double convexHullPerimeter(std::vector<Point> const& points) {
    if (points.size() < 3) return 0.0;

    // Graham scan algorithm
    auto pts = points;

    // Find bottom-most point (or left-most if tie)
    size_t min_idx = 0;
    for (size_t i = 1; i < pts.size(); ++i) {
        if (pts[i].y < pts[min_idx].y || 
            (pts[i].y == pts[min_idx].y && pts[i].x < pts[min_idx].x)) {
            min_idx = i;
        }
    }
    std::swap(pts[0], pts[min_idx]);
    Point pivot = pts[0];

    // Sort by polar angle with respect to pivot
    auto angle_cmp = [&](Point const& a, Point const& b) {
        double cross = (a.x - pivot.x) * (b.y - pivot.y) - 
                       (a.y - pivot.y) * (b.x - pivot.x);
        if (std::abs(cross) < 1e-9) {
            // Collinear: choose closer point first
            return distance(pivot, a) < distance(pivot, b);
        }
        return cross > 0;
    };
    std::sort(pts.begin() + 1, pts.end(), angle_cmp);

    // Build convex hull
    std::vector<Point> hull;
    hull.push_back(pts[0]);
    hull.push_back(pts[1]);

    auto ccw = [](Point const& a, Point const& b, Point const& c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x) > 0;
    };

    for (size_t i = 2; i < pts.size(); ++i) {
        while (hull.size() > 1 && 
               !ccw(hull[hull.size()-2], hull[hull.size()-1], pts[i])) {
            hull.pop_back();
        }
        hull.push_back(pts[i]);
    }

    // Compute perimeter in parallel using HPX
    std::vector<size_t> indices(hull.size());
    std::iota(indices.begin(), indices.end(), 0);

    return hpx::transform_reduce(
        hpx::execution::par,
        indices.begin(), indices.end(),
        0.0,
        std::plus<>(),
        [&](size_t i) {
            return distance(hull[i], hull[(i + 1) % hull.size()]);
        }
    );
}

