double convexHullPerimeter(std::vector<Point> const& points) {
    if (points.size() < 3) return 0.0;

    // Find bottom-most point (or left most in case of tie)
    auto bottom = *hpx::min_element(hpx::execution::par, points.begin(), points.end(),
        [](Point const& a, Point const& b) {
            return a.y < b.y || (a.y == b.y && a.x < b.x);
        });

    // Sort points by polar angle with respect to bottom point
    std::vector<Point> sorted = points;
    hpx::sort(hpx::execution::par, sorted.begin(), sorted.end(),
        [&bottom](Point const& a, Point const& b) {
            if (a.x == bottom.x && a.y == bottom.y) return true;
            if (b.x == bottom.x && b.y == bottom.y) return false;

            double angle_a = std::atan2(a.y - bottom.y, a.x - bottom.x);
            double angle_b = std::atan2(b.y - bottom.y, b.x - bottom.x);

            if (std::abs(angle_a - angle_b) < 1e-9) {
                return distance(bottom, a) < distance(bottom, b);
            }
            return angle_a < angle_b;
        });

    // Graham scan for convex hull
    auto cross = [](Point const& O, Point const& A, Point const& B) {
        return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
    };

    std::vector<Point> hull;
    for (auto const& p : sorted) {
        while (hull.size() >= 2 && cross(hull[hull.size()-2], hull[hull.size()-1], p) <= 0) {
            hull.pop_back();
        }
        hull.push_back(p);
    }

    // Compute perimeter in parallel using HPX
    std::vector<double> distances(hull.size());
    hpx::for_loop(hpx::execution::par, 0, hull.size(), [&](size_t i) {
        distances[i] = distance(hull[i], hull[(i + 1) % hull.size()]);
    });

    return hpx::reduce(hpx::execution::par, distances.begin(), distances.end(), 0.0);
}

