double convexHullPerimeter(std::vector<Point> const& points) {
    if (points.size() < 3) return 0.0;

    std::vector<Point> pts = points;

    // Find bottom-most point (or leftmost if tie)
    auto start = std::min_element(pts.begin(), pts.end(), 
        [](Point const& a, Point const& b) {
            return a.y < b.y || (a.y == b.y && a.x < b.x);
        });
    std::swap(pts[0], *start);
    Point pivot = pts[0];

    // Sort by polar angle
    std::sort(pts.begin() + 1, pts.end(), 
        [&pivot](Point const& a, Point const& b) {
            double cross = (a.x - pivot.x) * (b.y - pivot.y) - 
                          (a.y - pivot.y) * (b.x - pivot.x);
            if (cross == 0) {
                double da = std::pow(a.x - pivot.x, 2) + std::pow(a.y - pivot.y, 2);
                double db = std::pow(b.x - pivot.x, 2) + std::pow(b.y - pivot.y, 2);
                return da < db;
            }
            return cross > 0;
        });

    // Graham scan
    std::vector<Point> hull;
    hull.push_back(pts[0]);
    hull.push_back(pts[1]);

    for (size_t i = 2; i < pts.size(); ++i) {
        while (hull.size() > 1) {
            Point const& p2 = hull[hull.size() - 1];
            Point const& p1 = hull[hull.size() - 2];
            double cross = (p2.x - p1.x) * (pts[i].y - p1.y) - 
                          (p2.y - p1.y) * (pts[i].x - p1.x);
            if (cross <= 0) hull.pop_back();
            else break;
        }
        hull.push_back(pts[i]);
    }

    // Parallel perimeter calculation using HPX
    std::vector<size_t> indices(hull.size());
    std::iota(indices.begin(), indices.end(), 0);

    return hpx::transform_reduce(
        hpx::execution::par,
        indices.begin(), indices.end(),
        0.0,
        std::plus<>(),
        [&hull](size_t i) {
            return distance(hull[i], hull[(i + 1) % hull.size()]);
        }
    );
}

