    // Find pivot (lowest y, leftmost if tie)
    auto pivot = *std::min_element(points.begin(), points.end(),
        [](Point const& a, Point const& b) {
            return a.y < b.y || (a.y == b.y && a.x < b.x);
        });

    // Sort by polar angle relative to pivot
    std::vector<Point> sorted = points;
    std::sort(sorted.begin(), sorted.end(),
        [&pivot](Point const& a, Point const& b) {
            if (a.x == pivot.x && a.y == pivot.y) return true;
            if (b.x == pivot.x && b.y == pivot.y) return false;
            double cross = (a.x - pivot.x) * (b.y - pivot.y) - 
                          (b.x - pivot.x) * (a.y - pivot.y);
            if (cross != 0) return cross > 0;
            return distance(pivot, a) < distance(pivot, b);
        });

    // Graham scan to build convex hull
    auto ccw = [](Point const& a, Point const& b, Point const& c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x) > 0;
    };

    std::vector<Point> hull;
    for (auto const& p : sorted) {
        while (hull.size() > 1 && !ccw(hull[hull.size()-2], hull.back(), p)) {
            hull.pop_back();
        }
        hull.push_back(p);
    }

    // Compute perimeter in parallel using HPX
    std::vector<hpx::future<double>> futures;
    futures.reserve(hull.size());

    for (size_t i = 0; i < hull.size(); ++i) {
        size_t next = (i + 1) % hull.size();
        futures.push_back(hpx::async([p1 = hull[i], p2 = hull[next]]() {
            return distance(p1, p2);
        }));
    }

    // Sum all distances
    double perimeter = 0.0;
    for (auto& f : futures) {
        perimeter += f.get();
    }

    return perimeter;
}

