    // Create index pairs and compute minimum distance in parallel
    auto min_dist = hpx::experimental::transform_reduce(
        hpx::execution::par,
        hpx::util::counting_iterator<std::size_t>(0),
        hpx::util::counting_iterator<std::size_t>(num_pairs),
        std::numeric_limits<double>::infinity(),
        [](double a, double b) { return std::min(a, b); },  // reduce
        [&x, n](std::size_t idx) {  // transform
            // Convert linear index to (i, j) pair where i < j
            std::size_t i = 0;
