double closestPair(std::vector<double> const& x) {
    if (x.size() < 2) {
        return std::numeric_limits<double>::infinity();
    }

    // Sort for better cache locality and potential early termination
    std::vector<double> sorted_x = x;
    hpx::sort(hpx::execution::par, sorted_x.begin(), sorted_x.end());

    std::size_t n = sorted_x.size();

    // Use parallel transform_reduce to find minimum distance
    double min_dist = hpx::transform_reduce(
        hpx::execution::par,
        hpx::util::counting_iterator<std::size_t>(0),
        hpx::util::counting_iterator<std::size_t>(n - 1),
        std::numeric_limits<double>::infinity(),
        [](double a, double b) { return std::min(a, b); },  // Reduction
        [&sorted_x, n](std::size_t i) {                      // Transform
            double local_min = std::numeric_limits<double>::infinity();
            for (std::size_t j = i + 1; j < n; ++j) {
                double dist = distance(sorted_x[i], sorted_x[j]);
                local_min = std::min(local_min, dist);
                // Early termination: if sorted, no point checking further
                if (dist > local_min * 2) break;
            }
            return local_min;
        }
    );

    return min_dist;
}

