    }

    // Create indices for parallel iteration over first element of each pair
    std::vector<std::size_t> indices(x.size() - 1);
    std::iota(indices.begin(), indices.end(), 0);

    // Parallel transform_reduce: for each index i, find min distance to all j > i
    return hpx::transform_reduce(
        hpx::execution::par,
        indices.begin(), indices.end(),
        std::numeric_limits<double>::max(),
        [](double a, double b) { return std::min(a, b); },  // Reduce with min
        [&x](std::size_t i) {
            // Transform: find minimum distance from x[i] to all subsequent elements
            double min_dist = std::numeric_limits<double>::max();
            for (std::size_t j = i + 1; j < x.size(); ++j) {
                min_dist = std::min(min_dist, distance(x[i], x[j]));
            }
            return min_dist;
        }
    );
}

